-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_care_team_member.sql. Do not edit.
-- Silver care team member: one row per CareTeam.participant, so the care manager of a visit can be found.
-- The Riverside General feed sends one CareTeam per visit (attending, primary nurse, care manager from discharge).
CREATE OR REPLACE TABLE silver_care_team_member AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'CareTeam'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    l.resource_id                                                                       AS care_team_id,
    p.index                                                           AS member_index,
    REPLACE(l.raw:encounter.reference::string, 'Encounter/', '')                   AS encounter_id,
    REPLACE(l.raw:subject.reference::string, 'Patient/', '')                       AS patient_id,
    l.raw:status::string                                                           AS care_team_status,
    p.value:role[0].coding[0].code::string                                         AS role_code,
    REPLACE(p.value:member.reference::string, 'PractitionerRole/', '')             AS member_role_id,
    p.value:member.display::string                                                 AS member_name,
    TRY_CAST(SUBSTR(p.value:period.start::string, 1, 19) AS TIMESTAMP_NTZ)                                                 AS start_at,
    TRY_CAST(SUBSTR(p.value:period.end::string, 1, 19) AS TIMESTAMP_NTZ)                                                   AS end_at
FROM latest l , LATERAL FLATTEN(input => l.raw:participant) p;
